class Solution {
public:
    bool isFascinating(int n) {
        string s = to_string(n) + to_string(2 * n) + to_string(3 * n);
        int cnt[10] = {};
        for (char c : s) cnt[c - '0']++;
        if (cnt[0]) return false;
        for (int d = 1; d <= 9; d++) if (cnt[d] != 1) return false;
        return true;
    }
};

