class Solution {
    public boolean isFascinating(int n) {
        String s = "" + n + (2 * n) + (3 * n);
        int[] cnt = new int[10];
        for (char c : s.toCharArray()) cnt[c - '0']++;
        if (cnt[0] > 0) return false;
        for (int d = 1; d <= 9; d++) if (cnt[d] != 1) return false;
        return true;
    }
}

