var isFascinating = function(n) {
    const s = '' + n + (2 * n) + (3 * n);
    const cnt = Array(10).fill(0);
    for (const c of s) cnt[+c]++;
    return cnt[0] === 0 && cnt.slice(1).every(v => v === 1);
};
